/**
 * Opt-in Codex protocol tracing for debugging narrative and sub-agent wiring.
 *
 * Set `MCODE_CODEX_TRACE=1` before starting the server. Logs one `info` line per
 * ingested notification with redacted summaries (lengths and short previews only).
 */

import { logger } from "@mcode/shared";
import { AgentEventType } from "@mcode/contracts";
import type { AgentEvent } from "@mcode/contracts";

const TRUTHY = new Set(["1", "true", "yes"]);

/** Returns true when `MCODE_CODEX_TRACE` requests Codex ingest logging. */
export function isCodexTraceEnabled(): boolean {
  const v = process.env.MCODE_CODEX_TRACE;
  if (v == null || v === "") return false;
  return TRUTHY.has(v.trim().toLowerCase());
}

function previewText(s: string, max = 72): string {
  const t = s.replace(/\s+/g, " ").trim();
  if (t.length <= max) return t;
  return `${t.slice(0, max)}…`;
}

/** Pulls correlation ids from notification params when present (Codex app-server payloads). */
function traceCorrelationIds(
  params: Record<string, unknown> | undefined,
): Record<string, string> {
  if (!params || typeof params !== "object") return {};
  const out: Record<string, string> = {};
  for (const key of ["threadId", "turnId", "itemId"] as const) {
    const v = params[key];
    if (typeof v === "string" && v.length > 0) out[key] = v;
  }
  return out;
}

/**
 * Builds a compact, log-safe summary of codex JSON-RPC notification params
 * (no full prompts or command bodies).
 */
export function summarizeCodexNotificationParams(
  method: string,
  params: Record<string, unknown> | undefined,
): Record<string, unknown> {
  const ids = traceCorrelationIds(params);

  if (!params || typeof params !== "object") {
    return { ...ids, paramKeys: [] };
  }
  const baseKeys = Object.keys(params).filter((k) => k !== "item").slice(0, 20);

  if (method === "item/completed") {
    const item = params.item as Record<string, unknown> | undefined;
    const itemType = typeof item?.type === "string" ? item.type : undefined;
    const itemId = typeof item?.id === "string" ? item.id : undefined;
    const toolKind =
      typeof item?.toolKind === "string"
        ? item.toolKind
        : typeof item?.tool_kind === "string"
          ? item.tool_kind
          : undefined;
    const name = typeof item?.name === "string" ? item.name : undefined;
    return {
      ...ids,
      itemType,
      itemId,
      toolKind,
      functionName: name,
    };
  }

  if (
    method === "item/reasoning/textDelta"
    || method === "item/reasoning/summaryTextDelta"
    || method === "item/plan/delta"
    || method === "item/agentMessage/delta"
  ) {
    const rawDelta =
      typeof params.delta === "string"
        ? params.delta
        : typeof params.text === "string"
          ? params.text
          : "";
    return {
      ...ids,
      deltaLen: rawDelta.length,
      deltaPreview: rawDelta.length > 0 ? previewText(rawDelta, 64) : "",
    };
  }

  if (method === "item/started") {
    const item = params.item as Record<string, unknown> | undefined;
    return {
      ...ids,
      itemType: typeof item?.type === "string" ? item.type : undefined,
      itemId: typeof item?.id === "string" ? item.id : undefined,
    };
  }

  if (method === "turn/completed" || method === "turn/started") {
    const turn = params.turn as Record<string, unknown> | undefined;
    return {
      ...ids,
      turnId: typeof turn?.id === "string" ? turn.id : undefined,
      status: typeof turn?.status === "string" ? turn.status : undefined,
    };
  }

  return { ...ids, paramKeys: baseKeys };
}

/**
 * Maps emitted `AgentEvent` objects to compact trace records (ToolUse parent ids, delta flags).
 */
export function summarizeAgentEventsForTrace(events: readonly AgentEvent[]): unknown[] {
  return events.map((e) => {
    switch (e.type) {
      case AgentEventType.TextDelta:
        return {
          type: "textDelta",
          isFinalResponse: e.isFinalResponse === true,
          len: e.delta.length,
          preview: e.delta.length > 0 ? previewText(e.delta, 64) : "",
        };
      case AgentEventType.ToolUse:
        return {
          type: "toolUse",
          toolName: e.toolName,
          toolCallId: e.toolCallId,
          parentToolCallId: e.parentToolCallId,
          toolInputKeys: Object.keys(e.toolInput ?? {}).slice(0, 12),
        };
      case AgentEventType.ToolResult:
        return {
          type: "toolResult",
          toolCallId: e.toolCallId,
          isError: e.isError,
          outputLen: e.output.length,
        };
      case AgentEventType.Message:
        return {
          type: "message",
          contentLen: e.content.length,
        };
      case AgentEventType.TurnComplete:
        return { type: "turnComplete", tokensIn: e.tokensIn, tokensOut: e.tokensOut };
      case AgentEventType.Error:
        return { type: "error", errorLen: e.error.length };
      default:
        return { type: e.type };
    }
  });
}

/**
 * Logs a single notification and its mapped agent events when tracing is enabled.
 */
export function traceCodexIngest(
  threadId: string,
  method: string | undefined,
  params: Record<string, unknown> | undefined,
  events: readonly AgentEvent[],
): void {
  if (!isCodexTraceEnabled()) return;
  logger.info("Codex trace ingest", {
    threadId,
    method: method ?? "",
    raw: summarizeCodexNotificationParams(method ?? "", params),
    mapped: summarizeAgentEventsForTrace(events),
    mappedCount: events.length,
  });
}

#!/usr/bin/env node
// Minimal NDJSON JSON-RPC 2.0 client for `codex app-server`.
// Usage: node scripts/codex-trace.mjs <cwd> <traceOut> [prompt]
import { spawn } from "node:child_process";
import { appendFileSync, writeFileSync } from "node:fs";
import readline from "node:readline";

const [, , cwd, traceFile, scenarioLabel, prompt] = process.argv;
if (!cwd || !traceFile || !scenarioLabel || !prompt) {
  console.error("usage: codex-trace.mjs <cwd> <traceFile> <scenarioLabel> <prompt>");
  process.exit(2);
}

const proc = spawn("codex", ["app-server"], {
  cwd,
  stdio: ["pipe", "pipe", "pipe"],
  shell: true,
  windowsHide: true,
});

let nextId = 1;
const pending = new Map();
let seq = 0;
function logLine(obj) {
  appendFileSync(traceFile, JSON.stringify(obj) + "\n");
}
logLine({ event: "start", scenario: scenarioLabel, t: new Date().toISOString() });

function send(method, params) {
  const id = nextId++;
  const msg = { jsonrpc: "2.0", id, method, params };
  return new Promise((resolve, reject) => {
    pending.set(id, { resolve, reject, method });
    proc.stdin.write(JSON.stringify(msg) + "\n");
  });
}

const rl = readline.createInterface({ input: proc.stdout });
let resolveDone;
const done = new Promise((r) => { resolveDone = r; });

let activeTurnId = null;
let turnCompleted = false;

rl.on("line", (line) => {
  if (!line.trim()) return;
  let msg;
  try { msg = JSON.parse(line); } catch { return; }
  if (msg.id != null && pending.has(msg.id)) {
    const { resolve, reject, method } = pending.get(msg.id);
    pending.delete(msg.id);
    if (msg.error) reject(new Error(`${method} failed: ${msg.error.message}`));
    else resolve(msg.result);
    return;
  }
  if (msg.method) {
    seq++;
    const p = msg.params ?? {};
    const item = p.item ?? {};
    const summary = {
      seq,
      t: new Date().toISOString(),
      method: msg.method,
      threadId: p.threadId,
      turnId: p.turnId,
      itemId: p.itemId ?? item.id,
      itemType: item.type,
    };
    // include small fields when present
    if (typeof p.delta === "string") summary.deltaLen = p.delta.length;
    if (msg.method === "turn/completed") {
      summary.status = p.turn?.status;
      summary.itemsLen = Array.isArray(p.turn?.items) ? p.turn.items.length : null;
    }
    if (msg.method === "item/completed") {
      const it = p.item ?? {};
      if (typeof it.command === "string") summary.command = it.command.slice(0, 80);
      if (it.role) summary.role = it.role;
      if (typeof it.tool === "string") summary.tool = it.tool;
      if (Array.isArray(it.summary)) summary.summaryLen = it.summary.length;
      if (Array.isArray(it.reasoningContent)) summary.reasoningLen = it.reasoningContent.length;
    }
    logLine(summary);
    if (msg.method === "turn/completed" && p.turnId === activeTurnId) {
      turnCompleted = true;
      resolveDone();
    }
    if (msg.method === "error") {
      summary.errorMsg = p.error?.message;
      summary.willRetry = p.willRetry;
    }
  }
});

proc.stderr.on("data", (d) => {
  appendFileSync(traceFile, "STDERR: " + d.toString().slice(0, 500) + "\n");
});
proc.on("exit", (code) => {
  logLine({ event: "exit", code });
  if (!turnCompleted) resolveDone();
});

const timeout = setTimeout(() => {
  logLine({ event: "timeout" });
  resolveDone();
}, 120_000);

try {
  const initRes = await send("initialize", {
    clientInfo: { name: "mcode-trace", version: "0.0.1" },
    capabilities: { experimentalApi: true },
  });
  logLine({ event: "init/result", result: initRes });

  const ts = await send("thread/start", {
    cwd,
    approvalPolicy: "never",
    sandbox: "workspace-write",
  });
  logLine({ event: "thread/start/result", result: ts });
  const threadId = ts.thread?.id ?? ts.threadId;

  const turn = await send("turn/start", {
    threadId,
    input: [{ type: "text", text: prompt }],
  });
  activeTurnId = turn.turnId;
  logLine({ event: "turn/start/result", result: turn });

  await done;
} catch (err) {
  logLine({ event: "error", message: String(err?.message ?? err) });
} finally {
  clearTimeout(timeout);
  try { proc.stdin.end(); } catch {}
  setTimeout(() => proc.kill(), 1500);
}

