    const providerInput =
      interactionMode === "plan" ? this.buildPlanPrompt(stitchedContent) : stitchedContent;

    const resolvedCodexFast =
      codexFastMode !== undefined
        ? codexFastMode
        : parentThread.codex_fast_mode;
    if (provider === "codex" && resolvedCodexFast !== null) {
      this.threadRepo.updateSettings(thread.id, {
        codex_fast_mode: resolvedCodexFast,
      });
    }

    void this.sendMessage(
      thread.id,
      content,
      permissionMode,
      model,
      attachments,
      reasoningLevel,
      provider,
      interactionMode,
      maxBudgetUsd,
      maxTurns,
      copilotAgent,
      effectiveContextWindowMode,
      effectiveThinking,
      undefined,
      undefined,
      providerInput,
      undefined,
      undefined,
      displayContent,
    ).catch((err) => {
      logger.error("createBranchedThread initial send failed", {
        threadId: thread.id,
        error: err instanceof Error ? err.message : String(err),
      });
